        ->with(['user.profile', 'media', 'cover'])
        ->withCount([
            'comments',
            'reactions as likes_count' => fn ($query) => $query->where('type', 'like'),
            'bookmarks',
        ])
        ->published()
        ->latest('published_at')
        ->latest('id')
        ->limit(5)
