<script>
(()=>{const isEn=(document.documentElement.lang||'').toLowerCase().startsWith('en');const scroll=document.getElementById('momentsScroll');const slides=[...document.querySelectorAll('.moment-slide')];const prev=document.getElementById('previousMoment');const next=document.getElementById('nextMoment');const pos=document.getElementById('momentPosition');const dots=[...document.querySelectorAll('#momentDots i')];let active=0,wheelLock=false,drag=false,startY=0,startScroll=0,lastTap=0;document.querySelector('.main-nav-direct[href*="/moments"]')?.classList.add('active');const toast=m=>typeof showToast==='function'&&showToast(m);const setActive=i=>{active=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,n)=>{const on=n===active;s.classList.toggle('is-active',on);const video=s.querySelector('video');if(video){if(on&&!s.classList.contains('is-paused'))video.play().catch(()=>{});else video.pause()}});dots.forEach((d,n)=>d.classList.toggle('active',n===active));if(pos)pos.textContent=`${active+1} / ${slides.length}`;if(prev)prev.disabled=active===0;if(next)next.disabled=active===slides.length-1};const go=i=>{const target=slides[Math.max(0,Math.min(slides.length-1,i))];target&&scroll?.scrollTo({top:target.offsetTop,behavior:'smooth'})};let timer;scroll?.addEventListener('scroll',()=>{clearTimeout(timer);timer=setTimeout(()=>setActive(Math.round(scroll.scrollTop/(scroll.clientHeight||1))),55)},{passive:true});prev?.addEventListener('click',()=>go(active-1));next?.addEventListener('click',()=>go(active+1));scroll?.addEventListener('wheel',e=>{if(Math.abs(e.deltaY)<18||wheelLock||document.body.classList.contains('comments-open')||document.body.classList.contains('moment-create-open'))return;e.preventDefault();wheelLock=true;go(active+(e.deltaY>0?1:-1));setTimeout(()=>wheelLock=false,620)},{passive:false});scroll?.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.target.closest('button,a,input,textarea,select'))return;drag=true;startY=e.clientY;startScroll=scroll.scrollTop;scroll.classList.add('dragging');scroll.setPointerCapture(e.pointerId)});scroll?.addEventListener('pointermove',e=>{if(drag)scroll.scrollTop=startScroll-(e.clientY-startY)});const end=e=>{if(!drag)return;drag=false;scroll.classList.remove('dragging');try{scroll.releasePointerCapture(e.pointerId)}catch{}go(Math.round(scroll.scrollTop/(scroll.clientHeight||1)))};scroll?.addEventListener('pointerup',end);scroll?.addEventListener('pointercancel',end);document.querySelectorAll('.moment-play-toggle').forEach(b=>b.addEventListener('click',()=>{const slide=b.closest('.moment-slide');const video=slide?.querySelector('video');const paused=slide?.classList.toggle('is-paused');if(video){paused?video.pause():video.play().catch(()=>{})}b.innerHTML=`<svg><use href="#${paused?'i-play':'i-pause'}"></use></svg>`;b.setAttribute('aria-label',paused?@json($copy['play']):@json($copy['pause']))}));document.querySelectorAll('.moment-sound-toggle').forEach(b=>b.addEventListener('click',()=>{const video=b.closest('.moment-slide')?.querySelector('video');if(!video)return;video.muted=!video.muted;b.innerHTML=`<svg><use href="#${video.muted?'i-volume-off':'i-volume'}"></use></svg>`;b.setAttribute('aria-label',video.muted?@json($copy['unmute']):@json($copy['mute']));toast(video.muted?(isEn?'Sound off':'Ton ausgeschaltet'):(isEn?'Sound on':'Ton eingeschaltet'))}));document.querySelectorAll('.moment-follow-button').forEach(b=>b.addEventListener('click',()=>{const on=b.classList.toggle('following');b.innerHTML=`<svg><use href="#${on?'i-check':'i-plus'}"></use></svg>`;toast(on?(isEn?'Following this hunter':'Du folgst diesem Hunter'):(isEn?'No longer following':'Nicht mehr gefolgt'))}));document.querySelectorAll('.moment-share-button').forEach(b=>b.addEventListener('click',()=>toast(isEn?'Moment shared':'Moment geteilt')));document.querySelectorAll('.moment-action.like-button').forEach(b=>b.addEventListener('click',()=>setTimeout(()=>{const source=b.querySelector('[data-moment-count-source]');const visible=b.querySelector('[data-moment-count-visible]');if(source&&visible)visible.textContent=new Intl.NumberFormat(document.documentElement.lang||'de-DE').format(parseInt(source.textContent||'0',10)||0)},0)));slides.forEach(s=>s.addEventListener('pointerup',e=>{if(!['touch','pen'].includes(e.pointerType)||e.target.closest('button'))return;const now=Date.now();if(now-lastTap<330)s.querySelector('.like-button')?.click();lastTap=now}));document.querySelectorAll('[data-moments-feed]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-moments-feed]').forEach(x=>x.classList.toggle('active',x===b));go(0)}));const modal=document.getElementById('momentCreateModal'),open=document.getElementById('openMomentCreate'),close=document.getElementById('momentCreateClose'),cancel=document.getElementById('momentCreateCancel'),form=document.getElementById('momentCreateForm'),title=document.getElementById('momentCreateTitleInput');const openModal=()=>{modal?.classList.add('is-open');modal?.setAttribute('aria-hidden','false');document.body.classList.add('moment-create-open');setTimeout(()=>title?.focus(),120)};const closeModal=()=>{modal?.classList.remove('is-open');modal?.setAttribute('aria-hidden','true');document.body.classList.remove('moment-create-open')};open?.addEventListener('click',openModal);close?.addEventListener('click',closeModal);cancel?.addEventListener('click',closeModal);modal?.addEventListener('click',e=>e.target===modal&&closeModal());document.querySelectorAll('[data-moment-toast]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.momentToast)));form?.addEventListener('submit',e=>{e.preventDefault();if(!title?.value.trim()){title?.focus();toast(isEn?'Please enter a title':'Bitte einen Titel eingeben');return}closeModal();toast(isEn?'Moment published as demo':'Moment als Demo veröffentlicht');form.reset()});new MutationObserver(()=>document.querySelectorAll('#commentsList img[src^="assets/"]').forEach(img=>img.src=`/assets/themes/hnt_preview/dashboard-feed/${img.getAttribute('src')}`)).observe(document.getElementById('commentsList'),{childList:true,subtree:true});setActive(0);requestAnimationFrame(()=>{if(scroll)scroll.scrollTop=0})})();
</script>
